<script setup>
import { Head, Link, router } from '@inertiajs/vue3';
import SafeHtml from '@/Components/SafeHtml.vue';
import AdminLayout from '@/Layouts/AdminLayout.vue';
import { ArrowLeft, Mail, MessageSquare, Users, CheckCircle2, AlertCircle } from 'lucide-vue-next';
defineOptions({ layout: AdminLayout });
const props = defineProps({ campaign: Object, deliveries: Array, audiencePreview: Object });
const act = action => router.post(`/admin/erp/messaging/${props.campaign.id}/${action}`);
const date = value => value ? new Date(value).toLocaleString() : '—';
</script>
<template>
    <Head :title="campaign.name" />
    <div class="mx-auto max-w-5xl space-y-6">
        <Link href="/admin/erp/messaging" class="inline-flex min-h-11 items-center gap-2 text-sm text-surface-600 hover:text-primary-700"><ArrowLeft class="h-4 w-4" /> All campaigns</Link>
        <header class="flex flex-wrap items-start justify-between gap-4"><div><p class="mb-2 text-xs font-semibold uppercase tracking-widest text-surface-500">{{ campaign.channel }} campaign</p><h1 class="text-3xl font-display font-bold">{{ campaign.name }}</h1><p class="mt-2 text-sm text-surface-500">Created by {{ campaign.created_by?.full_name || 'your team' }}</p></div><span class="rounded-full border border-surface-200 bg-white px-4 py-2 text-xs font-medium capitalize">{{ campaign.status }}</span></header>
        <div class="flex flex-wrap gap-3"><button v-if="campaign.status === 'draft'" :disabled="!audiencePreview?.eligible" @click="act('send')" class="rounded-xl bg-primary-700 px-5 py-3 text-sm font-semibold text-white">Queue campaign</button><button v-if="['draft','scheduled','sending','paused'].includes(campaign.status)" @click="act('cancel')" class="rounded-xl border border-surface-300 bg-white px-5 py-3 text-sm font-medium">Cancel pending delivery</button><p class="self-center text-xs text-surface-500">Channel preferences and account access are checked before delivery. Messages already being sent may still arrive after cancellation.</p></div>
        <div v-if="deliveries?.some(item => item.status === 'uncertain')" role="status" class="rounded-xl border border-amber-300 bg-amber-50 p-4 text-sm text-amber-900">Some messages have an unknown provider acknowledgment. Check the provider before sending again.</div>
        <div v-if="audiencePreview" class="rounded-xl border border-primary-200 bg-primary-50 p-4 text-sm"><strong>{{ audiencePreview.eligible }} eligible recipients</strong><p class="mt-1 text-xs">{{ audiencePreview.excluded }} excluded · {{ audiencePreview.duplicates }} duplicates removed. Recipient eligibility may change before delivery.</p></div>
        <div class="grid grid-cols-3 gap-4"><div v-for="metric in [{ label: 'Recipients', value: campaign.recipient_count }, { label: 'Accepted', value: campaign.sent_count }, { label: 'Failed', value: campaign.failed_count }]" :key="metric.label" class="rounded-xl border border-surface-200 bg-white p-5"><p class="text-2xl font-semibold">{{ metric.value || 0 }}</p><p class="mt-1 text-xs text-surface-500">{{ metric.label }}</p></div></div>
        <section class="rounded-2xl border border-surface-200 bg-white p-6"><h2 class="font-semibold">Message content</h2><p v-if="campaign.subject" class="mt-4 font-medium">{{ campaign.subject }}</p><SafeHtml v-if="campaign.body_format === 'html'" :content="campaign.body" class="mt-4" /><pre v-else class="mt-3 whitespace-pre-wrap break-words font-sans text-sm leading-7 text-surface-600">{{ campaign.body }}</pre><dl class="mt-6 grid gap-4 border-t border-surface-100 pt-5 text-xs sm:grid-cols-2"><div><dt class="text-surface-500">Scheduled</dt><dd class="mt-1">{{ date(campaign.scheduled_at) }}</dd></div><div><dt class="text-surface-500">Completed</dt><dd class="mt-1">{{ date(campaign.completed_at) }}</dd></div></dl></section>
        <section class="overflow-hidden rounded-2xl border border-surface-200 bg-white"><div class="border-b border-surface-100 p-5"><h2 class="font-semibold">Delivery log</h2><p class="mt-1 text-xs text-surface-500">Up to 100 recorded deliveries. “Sent” means accepted by the provider, or placed in the platform inbox. It does not confirm that the recipient read it.</p></div><div v-if="campaign.logs?.length" class="overflow-x-auto"><table class="w-full text-left text-sm"><thead class="bg-surface-50 text-xs text-surface-500"><tr><th class="px-5 py-3" scope="col">Recipient</th><th class="px-5 py-3" scope="col">Status</th><th class="px-5 py-3" scope="col">Sent at</th></tr></thead><tbody><tr v-for="log in campaign.logs" :key="log.id" class="border-t border-surface-100"><td class="px-5 py-4">{{ campaign.channel === 'inbox' ? 'User #' + log.recipient : log.recipient }}</td><td class="px-5 py-4 capitalize">{{ deliveries?.find(item => item.messaging_log_id === log.id)?.status || log.status }}<p v-if="log.error_message" class="mt-1 text-xs text-surface-500">{{ log.error_message.replaceAll('_', ' ') }}</p></td><td class="px-5 py-4 text-surface-500">{{ date(log.sent_at) }}</td></tr></tbody></table></div><p v-else class="p-10 text-center text-sm text-surface-500">There are no delivery records for this campaign yet.</p></section>
    </div>
</template>
